-- French (frFR): the guide forever/reputation/bloodsail-buccaneers (forever/reputation/bloodsail-buccaneers.guide).
-- Written by `forge i18n guides sync frFR`, which keeps every translation (docs/TRANSLATING.md, "Guide texts").
-- Translate the right-hand sides; "" shows the English. Keep each {kind:id} as it is: the game shows its
-- name there in French (the English is listed above the line). A name the English has in the plural, as words,
-- may be written with the singular's token from its "plural, as words" line: "Bandidos ({npc:251918})", "{npc:251918} ×8".
-- A token marked "no name in this language" would show in English: write that name in French words instead.
-- The comments are rewritten by sync.
return {
	-- Guide
	["Bloodsail Buccaneers Reputation"] = "Réputation : La Voile sanglante",
	-- {item:10030} Admiral's Hat · {area:35} Booty Bay
	["The pirate outfit and the {item:10030}, bought with a war against {area:35} and every goblin town."] = "La tenue de pirate et le {item:10030}, payés par une guerre contre {area:35} et toutes les villes gobelines.",

	-- Step 1: Before you start
	["Before you start"] = "Avant de commencer",
	-- {area:35} Booty Bay · {area:976} Gadgetzan · {area:392} Ratchet · {area:2255} Everlook
	["Bloodsail standing goes up only by killing the people of {area:35}, and every kill costs you {area:35} 125 and the other goblin towns ({area:976}, {area:392}, {area:2255}, and in Forever likely Powderfuse) about 62 each. After the Bruisers this guide asks for, every goblin town is Hated: their guards attack you, and you lose their flight masters, inns, vendors and {area:976}'s and {area:2255}'s auction houses. Getting back takes longer than getting here (last step). Fly in, bind elsewhere, and do your goblin-town business first. The outfit and the hat need only Friendly; past that Bloodsail has nothing to give. {area:35}'s guards are not your enemies yet: tick At War for {area:35} in your reputation panel, then attack."] = "La réputation auprès de la Voile sanglante ne monte qu'en tuant les habitants de {area:35}, et chaque victime vous coûte 125 auprès de {area:35} et environ 62 auprès de chacune des autres villes gobelines ({area:976}, {area:392}, {area:2255}, et dans Forever sans doute Poudremèche). Après les Cogneurs que demande ce guide, toutes les villes gobelines sont Haï : leurs gardes vous attaquent, et vous perdez leurs maîtres de vol, auberges, marchands et les hôtels des ventes de {area:976} et de {area:2255}. Revenir prend plus longtemps que d'arriver ici (dernière étape). Venez en vol, liez votre pierre de foyer ailleurs et réglez d'abord vos affaires dans les villes gobelines. La tenue et le chapeau ne demandent qu'Amical ; au-delà, la Voile sanglante n'a plus rien à offrir. Les gardes de {area:35} ne sont pas encore vos ennemis : cochez En guerre pour {area:35} dans votre fenêtre de réputation, puis attaquez.",

	-- Step 2: Booty Bay Bruisers to Neutral
	-- plural, as words: Booty Bay Bruisers = {npc:4624} Booty Bay Bruiser
	["Booty Bay Bruisers to Neutral"] = "Cogneurs de Baie-du-Butin jusqu'à Neutre",
	-- {area:35} Booty Bay · {area:327} Faldir's Cove · {zone:1417} Arathi Highlands
	["Look at your Bloodsail bar first. A new character starts Hated, 500 short of Hostile: 260 Bruisers to Neutral, at 25 each. But every {area:35} quest you did while leveling took five times its {area:35} reward off Bloodsail (An OOX of Your Own, Stranglethorn Fever and Facing Negolash 1,000 each), and every Bloodsail pirate you killed 25 more: after {area:35}'s quests you sit near the bottom of Hated, up to 1,680 Bruisers from Neutral. Divide what the bar still lacks to Hostile, plus 6,000, by 25. Bruisers (level 57) hit hard, net you and knock you back, and new ones come when a goblin calls for help. Fight on the path that turns left from the tunnel up to the blacksmith's house: two Bruisers patrol it and rarely meet. Once they are down, step into the house (or hit one of the goblins inside) and a fresh Bruiser comes running. Players manage 30 to 40 an hour. {area:35} is Hated after about 53 Bruisers from a fresh Neutral 500. At the New Year celebration the town's goblins are drunk and do not fight back. The Blackwater crew at {area:327} in the {zone:1417} (level 37-40) are easier but pay only 5 each. Do not kill Bloodsail pirates: each costs 25."] = "Regardez d'abord votre barre de la Voile sanglante. Un nouveau personnage commence à Haï, à 500 de Hostile : 260 Cogneurs jusqu'à Neutre, à 25 chacun. Mais chaque quête de {area:35} faite en montant de niveau a retiré à la Voile sanglante cinq fois sa récompense de {area:35} (Un OOX rien que pour vous, La fièvre de Strangleronce et Face à Negolash 1 000 chacune), et chaque pirate de la Voile sanglante tué 25 de plus : après les quêtes de {area:35}, vous êtes près du fond de Haï, jusqu'à 1 680 Cogneurs de Neutre. Divisez par 25 ce qui manque encore à la barre pour Hostile, plus 6 000. Les Cogneurs (niveau 57) frappent fort, vous lancent des filets et vous repoussent, et d'autres arrivent quand un gobelin appelle à l'aide. Combattez sur le chemin qui part à gauche du tunnel et monte vers la maison du forgeron : deux Cogneurs y patrouillent et se croisent rarement. Une fois tombés, entrez dans la maison (ou frappez un des gobelins à l'intérieur) et un Cogneur frais accourt. Les joueurs en tuent 30 à 40 par heure. {area:35} est Haï après environ 53 Cogneurs depuis un Neutre frais à 500. Pendant la fête du Nouvel An, les gobelins de la ville sont ivres et ne se défendent pas. L'équipage de Blackwater à {area:327}, dans les {zone:1417} (niveau 37-40), est plus facile mais ne rapporte que 5 chacun. Ne tuez pas de pirates de la Voile sanglante : chacun coûte 25.",
	["the path to the smithy"] = "le chemin vers la forge",

	-- Step 3: Dressing the Part
	-- {npc:2546} Fleet Master Firallon · {area:1757} Crimson Veil · {area:35} Booty Bay · {item:22746} Buccaneer's Uniform · {item:22742} Bloodsail Shirt
	["At Neutral the Bloodsail crew stop attacking you. {npc:2546} is aboard the {area:1757}, the pirate ship anchored south of {area:35}, on its middle deck. Swim out; take the quest and hand it in on the spot for the {item:22746}: the {item:22742}, Sash, Pants and Boots."] = "À Neutre, l'équipage de la Voile sanglante cesse de vous attaquer. {npc:2546} est à bord du {area:1757}, le navire pirate ancré au sud de {area:35}, sur son pont du milieu. Rejoignez-le à la nage ; acceptez la quête et rendez-la sur place pour l'{item:22746} : la {item:22742}, la ceinture, le pantalon et les bottes.",
	-- {npc:2546} Fleet Master Firallon · {item:22746} Buccaneer's Uniform
	["{npc:2546}: the {item:22746}"] = "{npc:2546} : l'{item:22746}",

	-- Step 4: Bruisers to Friendly
	["Bruisers to Friendly"] = "Cogneurs jusqu'à Amical",
	["Neutral to Friendly is 3,000 more: 120 Bruisers. Friendly is the last standing that unlocks anything."] = "De Neutre à Amical, c'est 3 000 de plus : 120 Cogneurs. Amical est le dernier niveau de réputation qui débloque quelque chose.",

	-- Step 5: Avast Ye, Scallywag
	-- {area:35} Booty Bay
	["\"Pretty Boy\" Duncan, a Bloodsail pirate, stands on the beach north of {area:35}. {area:35} players kill him for a quest: if he is not there, wait for him. He has a quest for you from level 55, while {area:35} is below Neutral; it is done once you are Friendly with the Bloodsail and Hated with {area:35}."] = "Duncan « le Beau garçon », un pirate de la Voile sanglante, se tient sur la plage au nord de {area:35}. Les joueurs qui travaillent pour {area:35} le tuent pour une quête : s'il n'est pas là, attendez-le. Il a une quête pour vous dès le niveau 55, tant que {area:35} est sous Neutre ; elle est accomplie une fois Amical avec la Voile sanglante et Haï avec {area:35}.",
	-- {npc:2546} Fleet Master Firallon · {area:1757} Crimson Veil
	["{npc:2546}, on the {area:1757}: 25"] = "{npc:2546}, sur le {area:1757} : 25",

	-- Step 6: Avast Ye, Admiral!
	-- {npc:2496} Baron Revilgaz · {npc:2487} Fleet Master Seahorn · {area:35} Booty Bay
	["{npc:2496} and {npc:2487} stand on the top floor of the {area:35} inn, out on the balcony. Both are level 60 and Bruisers come to their aid: clear the stairs first and pull them one at a time. They come back, so a friend can kill them too."] = "{npc:2496} et {npc:2487} se tiennent au dernier étage de l'auberge de {area:35}, sur le balcon. Tous deux sont niveau 60 et des Cogneurs viennent à leur aide : nettoyez d'abord l'escalier et attirez-les un par un. Ils réapparaissent, donc un ami peut les tuer aussi.",

	-- Step 7: The Admiral's Hat
	-- {item:10030} Admiral's Hat
	["The {item:10030}"] = "Le {item:10030}",
	-- {item:12185} Bloodsail Admiral's Hat · {area:35} Booty Bay · {zone:1418} Badlands
	["Back to Firallon for the {item:12185} (in Classic its use calls a parrot to your shoulder): 200 more Bloodsail and 1,000 less {area:35}. Bruisers pay 25 only up to the end of Honored and Jazzrik, a lone goblin in the {zone:1418}, 5 up to the end of Revered; no quest is left, so Exalted cannot be reached."] = "Retournez voir Firallon pour le {item:12185} (dans Classic, son utilisation fait venir un perroquet sur votre épaule) : 200 de plus avec la Voile sanglante et 1 000 de moins avec {area:35}. Les Cogneurs rapportent 25 seulement jusqu'à la fin d'Honoré, et Jazzrik, un gobelin solitaire des {zone:1418}, 5 jusqu'à la fin de Révéré ; il ne reste aucune quête, donc Exalté est hors d'atteinte.",

	-- Step 8: The way back
	["The way back"] = "Le retour",
	-- {area:392} Ratchet · {area:35} Booty Bay · {area:976} Gadgetzan · {area:2255} Everlook · {npc:14637} Zorbin Fandazzle · {zone:1444} Feralas
	["Every goblin town is now Hated. Forever's quest data takes the town reputation off the four goblin amends quests outside {area:392}, {area:35}, {area:976} and {area:2255}, so the climb back is the Cartel's own: {npc:14637} in {zone:1444} serves everyone, and his Zapped Giants quests pay 25 to every town at once; Bloodsail pirates give {area:35} 5 each up to the end of Neutral (and cost Bloodsail 25); Southsea pirates and the Venture Co. in Stranglethorn give the towns 5 each. The Steamwheedle Cartel guide has the details. Expect it to take longer than the war did."] = "Toutes les villes gobelines sont maintenant Haï. Les données de quêtes de Forever retirent la réputation des villes aux quatre quêtes gobelines de réparation hors de {area:392}, {area:35}, {area:976} et {area:2255} : la remontée passe donc par le Cartel lui-même. {npc:14637}, dans {zone:1444}, sert tout le monde, et ses quêtes Géants rétrécis rapportent 25 à toutes les villes à la fois ; les pirates de la Voile sanglante donnent 5 chacun à {area:35} jusqu'à la fin de Neutre (et coûtent 25 auprès de la Voile sanglante) ; les pirates des Mers du Sud et la KapitalRisk à Strangleronce donnent 5 chacun aux villes. Le guide du Cartel Gentepression a les détails. Attendez-vous à ce que ce soit plus long que la guerre.",
	-- {npc:14637} Zorbin Fandazzle
	["{npc:14637}: Zapped Giants, open to the Hated"] = "{npc:14637} : Géants rétrécis, ouvert même à Haï",
}
